window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-60d486a8abb3579e"]={"versions": [{"id": "FIG-60d486a8abb3579e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Execution-Trace-Diagramm) zur Multicore-Synchronisation im AUTOSAR-Betriebssystem (<code>AUTOSAR_SWS_OS</code>). Das Diagramm illustriert das Nebenläufigkeitsverhalten zweier Rechenkerne beim Einsatz verschachtelter Spinlocks und visualisiert ein klassisches Deadlock-Szenario (zyklische Blockade/Wechselseitiges Warten).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungseinheiten / Kerne:</strong></li>\n<li><code>Core 0</code>: Erster Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><code>Core 1</code>: Zweiter Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><strong>Synchronisationsobjekte:</strong></li>\n<li>Spinlock <code>A</code>: Erste Sperrvariable.</li>\n<li>Spinlock <code>B</code>: Zweite Sperrvariable.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>GetSpinLock(A)</code>: OS-API-Aufruf zur Belegung von Spinlock A.</li>\n<li><code>GetSpinLock(B)</code>: OS-API-Aufruf zur Belegung von Spinlock B.</li>\n<li><code>Do something</code>: Phase der Nutzlastausführung im geschützten Bereich.</li>\n<li><code>Spin for lock B</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 0.</li>\n<li><code>Spin for lock A</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 1.</li>\n<li><strong>Annotation:</strong></li>\n<li><code>Deadlock caused by different nesting order.</code> mit wechselseitig kreuzenden Pfeilen zwischen den Blockierungs- und Belegungszuständen.</li>\n<li><strong>Zeitachse:</strong> Horizontale Zeitachse <code>t</code> am oberen Bildrand mit diskreten Takten/Intervallen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 (Initialer Lock-Erwerb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zeitgleich fordert <code>Core 0</code> über <code>GetSpinLock(A)</code> erfolgreich Spinlock A an und belegt diesen.</li>\n<li>Zeitgleich fordert <code>Core 1</code> über <code>GetSpinLock(B)</code> erfolgreich Spinlock B an und belegt diesen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 (Verarbeitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beide Kerne führen innerhalb ihrer jeweiligen kritischen Abschnitte Instruktionen aus (<code>Do something</code>). Spinlock A bleibt durch <code>Core 0</code> gehalten, Spinlock B durch <code>Core 1</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 (Verschachtelte Lock-Anforderung / Nested Lock Call):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Core 0</code> ruft <code>GetSpinLock(B)</code> auf, um zusätzlich Spinlock B zu akquirieren. Da Spinlock B jedoch von <code>Core 1</code> gehalten wird, geht <code>Core 0</code> in eine aktive Warteschleife über (<code>Spin for lock B</code>).</li>\n<li><code>Core 1</code> ruft <code>GetSpinLock(A)</code> auf, um zusätzlich Spinlock A zu akquirieren. Da Spinlock A von <code>Core 0</code> gehalten wird, geht <code>Core 1</code> in eine aktive Warteschleife über (<code>Spin for lock A</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 (Deadlock-Zustand):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Keiner der Kerne kann die Ausführung fortsetzen oder den bereits gehaltenen Lock freigeben (<code>ReleaseSpinLock</code>). Es resultiert ein permanenter Deadlock durch invertierte Akquisitionsreihenfolge (Core 0: A $\\to$ B; Core 1: B $\\to$ A).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Deadlocks (Lock Ordering):</strong> Wenn Tasks oder ISRs mehrere Spinlocks verschachtelt belegen müssen, muss im Gesamtsystem eine strikte, globale Belegungsreihenfolge (Zuteilungsordnung) aller Spinlocks definiert und eingehalten werden.</li>\n<li><strong>Konfigurations- und OS-Regeln:</strong> Die AUTOSAR-OS-Spezifikation fordert Restriktionen bei verschachtelten Spinlocks (z. B. Überprüfung der Zuteilungsreihenfolge bei konfigurierter Spinlock-Schachtelung), um zyklische Abhängigkeiten zur Laufzeit auszuschließen.</li>\n<li><strong>Vermeidung von Busy-Waiting-Blockaden:</strong> Da das Warten auf Spinlocks aktiv Rechenzeit bindet, führen zirkuläre Abhängigkeiten zum vollständigen Blockieren aller beteiligten Prozessorkerne.</li>\n</ul>"}, {"id": "FIG-5d705a88d17931d0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Execution-Trace-Diagramm) zur Multicore-Synchronisation im AUTOSAR-Betriebssystem (<code>AUTOSAR_SWS_OS</code>). Das Diagramm illustriert das Nebenläufigkeitsverhalten zweier Rechenkerne beim Einsatz verschachtelter Spinlocks und visualisiert ein klassisches Deadlock-Szenario (zyklische Blockade/Wechselseitiges Warten).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungseinheiten / Kerne:</strong></li>\n<li><code>Core 0</code>: Erster Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><code>Core 1</code>: Zweiter Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><strong>Synchronisationsobjekte:</strong></li>\n<li>Spinlock <code>A</code>: Erste Sperrvariable.</li>\n<li>Spinlock <code>B</code>: Zweite Sperrvariable.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>GetSpinLock(A)</code>: OS-API-Aufruf zur Belegung von Spinlock A.</li>\n<li><code>GetSpinLock(B)</code>: OS-API-Aufruf zur Belegung von Spinlock B.</li>\n<li><code>Do something</code>: Phase der Nutzlastausführung im geschützten Bereich.</li>\n<li><code>Spin for lock B</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 0.</li>\n<li><code>Spin for lock A</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 1.</li>\n<li><strong>Annotation:</strong></li>\n<li><code>Deadlock caused by different nesting order.</code> mit wechselseitig kreuzenden Pfeilen zwischen den Blockierungs- und Belegungszuständen.</li>\n<li><strong>Zeitachse:</strong> Horizontale Zeitachse <code>t</code> am oberen Bildrand mit diskreten Takten/Intervallen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 (Initialer Lock-Erwerb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zeitgleich fordert <code>Core 0</code> über <code>GetSpinLock(A)</code> erfolgreich Spinlock A an und belegt diesen.</li>\n<li>Zeitgleich fordert <code>Core 1</code> über <code>GetSpinLock(B)</code> erfolgreich Spinlock B an und belegt diesen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 (Verarbeitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beide Kerne führen innerhalb ihrer jeweiligen kritischen Abschnitte Instruktionen aus (<code>Do something</code>). Spinlock A bleibt durch <code>Core 0</code> gehalten, Spinlock B durch <code>Core 1</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 (Verschachtelte Lock-Anforderung / Nested Lock Call):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Core 0</code> ruft <code>GetSpinLock(B)</code> auf, um zusätzlich Spinlock B zu akquirieren. Da Spinlock B jedoch von <code>Core 1</code> gehalten wird, geht <code>Core 0</code> in eine aktive Warteschleife über (<code>Spin for lock B</code>).</li>\n<li><code>Core 1</code> ruft <code>GetSpinLock(A)</code> auf, um zusätzlich Spinlock A zu akquirieren. Da Spinlock A von <code>Core 0</code> gehalten wird, geht <code>Core 1</code> in eine aktive Warteschleife über (<code>Spin for lock A</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 (Deadlock-Zustand):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Keiner der Kerne kann die Ausführung fortsetzen oder den bereits gehaltenen Lock freigeben (<code>ReleaseSpinLock</code>). Es resultiert ein permanenter Deadlock durch invertierte Akquisitionsreihenfolge (Core 0: A $\\to$ B; Core 1: B $\\to$ A).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Deadlocks (Lock Ordering):</strong> Wenn Tasks oder ISRs mehrere Spinlocks verschachtelt belegen müssen, muss im Gesamtsystem eine strikte, globale Belegungsreihenfolge (Zuteilungsordnung) aller Spinlocks definiert und eingehalten werden.</li>\n<li><strong>Konfigurations- und OS-Regeln:</strong> Die AUTOSAR-OS-Spezifikation fordert Restriktionen bei verschachtelten Spinlocks (z. B. Überprüfung der Zuteilungsreihenfolge bei konfigurierter Spinlock-Schachtelung), um zyklische Abhängigkeiten zur Laufzeit auszuschließen.</li>\n<li><strong>Vermeidung von Busy-Waiting-Blockaden:</strong> Da das Warten auf Spinlocks aktiv Rechenzeit bindet, führen zirkuläre Abhängigkeiten zum vollständigen Blockieren aller beteiligten Prozessorkerne.</li>\n</ul>"}, {"id": "FIG-99158c4f1e7cce38", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Execution-Trace-Diagramm) zur Multicore-Synchronisation im AUTOSAR-Betriebssystem (<code>AUTOSAR_SWS_OS</code>). Das Diagramm illustriert das Nebenläufigkeitsverhalten zweier Rechenkerne beim Einsatz verschachtelter Spinlocks und visualisiert ein klassisches Deadlock-Szenario (zyklische Blockade/Wechselseitiges Warten).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungseinheiten / Kerne:</strong></li>\n<li><code>Core 0</code>: Erster Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><code>Core 1</code>: Zweiter Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><strong>Synchronisationsobjekte:</strong></li>\n<li>Spinlock <code>A</code>: Erste Sperrvariable.</li>\n<li>Spinlock <code>B</code>: Zweite Sperrvariable.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>GetSpinLock(A)</code>: OS-API-Aufruf zur Belegung von Spinlock A.</li>\n<li><code>GetSpinLock(B)</code>: OS-API-Aufruf zur Belegung von Spinlock B.</li>\n<li><code>Do something</code>: Phase der Nutzlastausführung im geschützten Bereich.</li>\n<li><code>Spin for lock B</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 0.</li>\n<li><code>Spin for lock A</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 1.</li>\n<li><strong>Annotation:</strong></li>\n<li><code>Deadlock caused by different nesting order.</code> mit wechselseitig kreuzenden Pfeilen zwischen den Blockierungs- und Belegungszuständen.</li>\n<li><strong>Zeitachse:</strong> Horizontale Zeitachse <code>t</code> am oberen Bildrand mit diskreten Takten/Intervallen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 (Initialer Lock-Erwerb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zeitgleich fordert <code>Core 0</code> über <code>GetSpinLock(A)</code> erfolgreich Spinlock A an und belegt diesen.</li>\n<li>Zeitgleich fordert <code>Core 1</code> über <code>GetSpinLock(B)</code> erfolgreich Spinlock B an und belegt diesen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 (Verarbeitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beide Kerne führen innerhalb ihrer jeweiligen kritischen Abschnitte Instruktionen aus (<code>Do something</code>). Spinlock A bleibt durch <code>Core 0</code> gehalten, Spinlock B durch <code>Core 1</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 (Verschachtelte Lock-Anforderung / Nested Lock Call):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Core 0</code> ruft <code>GetSpinLock(B)</code> auf, um zusätzlich Spinlock B zu akquirieren. Da Spinlock B jedoch von <code>Core 1</code> gehalten wird, geht <code>Core 0</code> in eine aktive Warteschleife über (<code>Spin for lock B</code>).</li>\n<li><code>Core 1</code> ruft <code>GetSpinLock(A)</code> auf, um zusätzlich Spinlock A zu akquirieren. Da Spinlock A von <code>Core 0</code> gehalten wird, geht <code>Core 1</code> in eine aktive Warteschleife über (<code>Spin for lock A</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 (Deadlock-Zustand):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Keiner der Kerne kann die Ausführung fortsetzen oder den bereits gehaltenen Lock freigeben (<code>ReleaseSpinLock</code>). Es resultiert ein permanenter Deadlock durch invertierte Akquisitionsreihenfolge (Core 0: A $\\to$ B; Core 1: B $\\to$ A).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Deadlocks (Lock Ordering):</strong> Wenn Tasks oder ISRs mehrere Spinlocks verschachtelt belegen müssen, muss im Gesamtsystem eine strikte, globale Belegungsreihenfolge (Zuteilungsordnung) aller Spinlocks definiert und eingehalten werden.</li>\n<li><strong>Konfigurations- und OS-Regeln:</strong> Die AUTOSAR-OS-Spezifikation fordert Restriktionen bei verschachtelten Spinlocks (z. B. Überprüfung der Zuteilungsreihenfolge bei konfigurierter Spinlock-Schachtelung), um zyklische Abhängigkeiten zur Laufzeit auszuschließen.</li>\n<li><strong>Vermeidung von Busy-Waiting-Blockaden:</strong> Da das Warten auf Spinlocks aktiv Rechenzeit bindet, führen zirkuläre Abhängigkeiten zum vollständigen Blockieren aller beteiligten Prozessorkerne.</li>\n</ul>"}, {"id": "FIG-b8f502f2782a9a7c", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Execution-Trace-Diagramm) zur Multicore-Synchronisation im AUTOSAR-Betriebssystem (<code>AUTOSAR_SWS_OS</code>). Das Diagramm illustriert das Nebenläufigkeitsverhalten zweier Rechenkerne beim Einsatz verschachtelter Spinlocks und visualisiert ein klassisches Deadlock-Szenario (zyklische Blockade/Wechselseitiges Warten).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungseinheiten / Kerne:</strong></li>\n<li><code>Core 0</code>: Erster Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><code>Core 1</code>: Zweiter Ausführungskern mit sequenzieller Abarbeitung.</li>\n<li><strong>Synchronisationsobjekte:</strong></li>\n<li>Spinlock <code>A</code>: Erste Sperrvariable.</li>\n<li>Spinlock <code>B</code>: Zweite Sperrvariable.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>GetSpinLock(A)</code>: OS-API-Aufruf zur Belegung von Spinlock A.</li>\n<li><code>GetSpinLock(B)</code>: OS-API-Aufruf zur Belegung von Spinlock B.</li>\n<li><code>Do something</code>: Phase der Nutzlastausführung im geschützten Bereich.</li>\n<li><code>Spin for lock B</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 0.</li>\n<li><code>Spin for lock A</code>: Aktives Warten (Busy Waiting / Polling) auf Kern 1.</li>\n<li><strong>Annotation:</strong></li>\n<li><code>Deadlock caused by different nesting order.</code> mit wechselseitig kreuzenden Pfeilen zwischen den Blockierungs- und Belegungszuständen.</li>\n<li><strong>Zeitachse:</strong> Horizontale Zeitachse <code>t</code> am oberen Bildrand mit diskreten Takten/Intervallen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 (Initialer Lock-Erwerb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zeitgleich fordert <code>Core 0</code> über <code>GetSpinLock(A)</code> erfolgreich Spinlock A an und belegt diesen.</li>\n<li>Zeitgleich fordert <code>Core 1</code> über <code>GetSpinLock(B)</code> erfolgreich Spinlock B an und belegt diesen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 (Verarbeitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beide Kerne führen innerhalb ihrer jeweiligen kritischen Abschnitte Instruktionen aus (<code>Do something</code>). Spinlock A bleibt durch <code>Core 0</code> gehalten, Spinlock B durch <code>Core 1</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 (Verschachtelte Lock-Anforderung / Nested Lock Call):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Core 0</code> ruft <code>GetSpinLock(B)</code> auf, um zusätzlich Spinlock B zu akquirieren. Da Spinlock B jedoch von <code>Core 1</code> gehalten wird, geht <code>Core 0</code> in eine aktive Warteschleife über (<code>Spin for lock B</code>).</li>\n<li><code>Core 1</code> ruft <code>GetSpinLock(A)</code> auf, um zusätzlich Spinlock A zu akquirieren. Da Spinlock A von <code>Core 0</code> gehalten wird, geht <code>Core 1</code> in eine aktive Warteschleife über (<code>Spin for lock A</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 (Deadlock-Zustand):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Keiner der Kerne kann die Ausführung fortsetzen oder den bereits gehaltenen Lock freigeben (<code>ReleaseSpinLock</code>). Es resultiert ein permanenter Deadlock durch invertierte Akquisitionsreihenfolge (Core 0: A $\\to$ B; Core 1: B $\\to$ A).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Deadlocks (Lock Ordering):</strong> Wenn Tasks oder ISRs mehrere Spinlocks verschachtelt belegen müssen, muss im Gesamtsystem eine strikte, globale Belegungsreihenfolge (Zuteilungsordnung) aller Spinlocks definiert und eingehalten werden.</li>\n<li><strong>Konfigurations- und OS-Regeln:</strong> Die AUTOSAR-OS-Spezifikation fordert Restriktionen bei verschachtelten Spinlocks (z. B. Überprüfung der Zuteilungsreihenfolge bei konfigurierter Spinlock-Schachtelung), um zyklische Abhängigkeiten zur Laufzeit auszuschließen.</li>\n<li><strong>Vermeidung von Busy-Waiting-Blockaden:</strong> Da das Warten auf Spinlocks aktiv Rechenzeit bindet, führen zirkuläre Abhängigkeiten zum vollständigen Blockieren aller beteiligten Prozessorkerne.</li>\n</ul>"}], "trans": [{"from": "FIG-60d486a8abb3579e", "to": "FIG-5d705a88d17931d0", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d705a88d17931d0", "to": "FIG-99158c4f1e7cce38", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-99158c4f1e7cce38", "to": "FIG-b8f502f2782a9a7c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
